import { useState } from 'react'
import { supabase } from '../../../lib/supabase'
const flags: Record<string,string> = {"CN": "data:image/png;base64,", "TR": "data:image/png;base64,", "AE": "data:image/png;base64,", "SA": "data:image/png;base64,", "FR": "data:image/png;base64,", "US": "data:image/png;base64,", "ES": "data:image/png;base64,"}
export default function EsimFlag({flag,code,path}:{flag:string;code:string;path?:string|null}) {
 const iso=code.toUpperCase(); const [failed,setFailed]=useState('');
 const uploaded=path?supabase.storage.from('esim-country-images').getPublicUrl(path).data.publicUrl:''
 const src=uploaded&&failed!==uploaded?uploaded:flags[iso]||''
 return <span className="inline-flex h-8 w-11 shrink-0 items-center justify-center overflow-hidden rounded-md bg-slate-100 dark:bg-slate-800" title={iso}>{src?<img src={src} alt={iso} onError={()=>setFailed(src)} className="h-full w-full object-contain"/>:<span className="text-sm">{flag||iso}</span>}</span>
}
